        body: 'یکی از شایع‌ترین مراجعات اورژانسی والدین به کلینیک، مشاهده یک یا دو دندان دائمی سفید در پشت دندان‌های شیری قدامی فک پایین است؛ پدیده‌ای که در اصطلاح عامیانه به «دندان کوسه‌ای» (Shark Teeth) شهرت دارد. این اتفاق زمانی رخ می‌دهد که جوانه دندان دائمی به سمت زبان متمایل بوده و نتوانسته ریشه دندان شیری جلوی خود را بر اساس روند طبیعی [آناتومی و تحلیل فیزیولوژیک ریشه دندان شیری](/articles/primary-baby-teeth-guide#primary-teeth-anatomy-roots-and-nerves) به طور کامل تحلیل ببرد. در اغلب موارد، با لق شدن تدریجی، دندان شیری طی چند هفته می‌افتد و نیروی رو به جلوی زبان، دندان دائمی را به ردیف اصلی خود هدایت می‌کند. اما چنانچه دندان شیری محکم مانده، هیچ لقی ندارد و سن کودک از ۷ یا ۸ سالگی گذشته است، باید توسط دندانپزشک کشیده شود تا مسیر رویش کاملاً آزاد گردد.',
