        body: 'یکی از خطرناک‌ترین باورهای سنتی و غلط در مراقبت از کودک، انتساب تب شدید، اسهال آبکی یا استفراغ به «دندان‌درآوردن» است! از دیدگاه پزشکی و بر اساس مطالعات آکادمی اطفال آمریکا (AAP)، رویش دندان حداکثر می‌تواند باعث گرم شدن بسیار خفیف بدن (افزایش دمای کمتر از ۰.۵ درجه سانتی‌گراد، زیر ۳۸ درجه) شود، اما هرگز عامل تب واقعی بالای ۳۸ درجه، اسهال مکرر و بی‌حالی نیست.\n\nعلت واقعی چیست؟ در سنین ۶ تا ۱۲ ماهگی، از یک سو ایمنی انتقالی از مادر کاهش یافته و سیستم ایمنی نوزاد مستعد عفونت‌های ویروسی می‌شود؛ از سوی دیگر نوزاد به دلیل خارش شدید لثه، هر شیء آلوده، دست یا اسباب‌بازی را به دهان می‌برد که سبب ورود میکروب‌ها و بروز اسهال یا گاستروانتریت می‌گردد. نادیده گرفتن تب بالا یا اسهال به بهانه دندان‌درآوردن ممکن است درمان یک عفونت حاد مانند عفونت گوش یا ادراری را به تاخیر بیندازد؛ بنابراین در صورت وجود تب بالای ۳۸ درجه یا اسهال مداوم، مراجعه فوری به پزشک اطفال الزامی است.',
