        body: 'دندانپزشکان اطفال و متخصصان ارتودنسی توصیه می‌کنند که استفاده از پستانک باید بین **۲ الی ۳ سالگی** به طور کامل متوقف شود. اگر عادت مکیدن تا پیش از این سن متوقف گردد، در بسیاری از کودکان ناهنجاری‌های اولیه فک و دندان با رشد طبیعی بافت‌ها خودبه‌خود اصلاح می‌شوند. اما تداوم عادت پس از ۴ سالگی باعث تثبیت تغییر شکل استخوان فک شده و اثرات آن بر دندان‌های دائمی نیز باقی می‌ماند.\n\nراهکارهای اصولی برای کمک به کودک جهت ترک پستانک:\n۱. **پرهیز از تنبیه و خشونت:** سرزنش و تنبیه صرفاً اضطراب کودک را تشدید کرده و او را به سمت مکیدن پنهانی سوق می‌دهد.\n۲. **سیستم پاداش و تشویق:** برای شب‌هایی که کودک بدون پستانک می‌خوابد، جدول ستاره یا جوایز کوچک معنوی در نظر بگیرید.\n۳. **جایگزین‌های آرامش‌بخش:** برای آرامش خواب کودک، از کتاب خواندن، در آغوش گرفتن و عروسک‌های نرم محبوب او استفاده کنید.\n۴. **پایان تدریجی:** پستانک را ابتدا در طول روز و سپس در خواب نیمروزی محدود کرده و در مرحله آخر در خواب شبانه حذف نمایید.',
