        body: 'بیماری‌های لثه در طبقه‌بندی دندانپزشکی به دو فاز بنیادین تقسیم می‌شوند که شناخت تفاوت آن‌ها برای حفظ سلامت دندان‌ها حیاتی است:\n\n۱. **ژنژیویت (Gingivitis - التهاب لثه سطحی):**\n- در این مرحله، التهاب فقط به بافت نرم لثه محدود است و استخوان نگهدارنده دندان و الیاف پریودنتال کاملاً سالم هستند.\n- مشخصه بارز: قرمزی، پف‌کردگی و خونریزی هنگام مسواک زدن بدون وجود لقی دندان.\n- خبر خوب: ژنژیویت یک مرحله ۱۰۰٪ برگشت‌پذیر است. با بهبود شیوه مسواک زدن، استفاده مرتب از نخ دندان و یک جلسه جرم‌گیری در مطب، لثه ظرف ۷ تا ۱۰ روز سلامت و قوام اولیه خود را بازمی‌یابد.\n\n۲. **پریودنتیت (Periodontitis - تخریب بافت‌های عمقی و استخوان فک):**\n- اگر ژنژیویت درمان نشود، عفونت به زیر خط لثه نفوذ کرده و به الیاف نگه‌دارنده و استخوان آلوئولار فک حمله می‌کند.\n- با ذوب شدن تدریجی استخوان، بین دندان و لثه پاکت‌های عمیقی ایجاد می‌شود که محل انباشت باکتری‌های بی‌هوازی مهاجم است.\n- عوارض: لقی دندان، بیرون زدن ریشه، جابجایی دندان‌ها و در نهایت از دست رفتن دندان سالم به دلیل تحلیل رفتن بستر استخوانی آن.\n- برخلاف ژنژیویت، استخوان از دست رفته در پریودنتیت به صورت خودبه‌خودی بازنمی‌گردد و درمان صرفاً با هدف توقف پیشرفت بیماری انجام می‌گیرد.',
