        body: 'بیماری لثه غالباً یک بیماری «خاموش و بدون درد» است؛ یعنی برعکس پوسیدگی دندان که با درد عصب بیمار را وادار به مراجعه می‌کند، عفونت لثه می‌تواند سال‌ها بدون درد استخوان فک را تخریب نماید. به همین دلیل باید علائم اولیه را به موقع شناسایی کنید:\n\nعلائم بالینی هشداردهنده بیماری لثه:\n- **تغییر رنگ لثه:** تبدیل رنگ صورتی ملایم و مات به قرمز پررنگ، کبود یا براق.\n- **تورم و لبه‌های گرد لثه:** از دست رفتن فرم کنگره‌ای چاقویی لثه و تبدیل آن به بافتی متورم و اسفنجی.\n- **بوی بد و طعم ناخوشایند دائمی در دهان:** ناشی از گازهای گوگردی تولیدشده توسط باکتری‌های بی‌هوازی زیر لثه.\n- **پایین رفتن لثه و بلندتر به نظر رسیدن دندان‌ها:** نمایان شدن سطح ریشه زردتر و بروز حساسیت به آب سرد و گرم.\n- **ترشح چرک در خط لثه:** مشاهده مایع زرد یا سفیدرنگ هنگام فشار دادن آرام لثه با انگشت.\n- **فاصله‌افتادن بین دندان‌ها یا احساس لقی خفیف:** تغییر موقعیت دندان‌ها هنگام جویدن غذا یا احساس این که دندان‌ها روی هم جفت نمی‌شوند.',
