        body: 'اثربخشی مسواک زدن بیش از آنکه به مارک خمیردندان وابسته باشد، به رعایت زمان‌بندی و دفعات مربوط است:\n\n۱. **حداقل دفعات:** مسواک زدن باید حداقل **۲ بار در روز** (یک‌بار صبح پس از صبحانه و مهم‌تر از همه شب قبل از خواب) انجام شود. در طول خواب ترشح بزاق محافظ به شدت افت می‌کند؛ بنابراین خوابیدن بدون مسواک، جشنی شبانه برای تکثیر باکتری‌های پوسیدگی‌زاست.\n\n۲. **مدت زمان استاندارد (۲ دقیقه کامل):** تحقیقات نشان می‌دهد میانگین مسواک زدن افراد در دنیای واقعی تنها حدود ۴۵ ثانیه است! برای پاکسازی تمام سطوح دهان، فک بالا و پایین را به ۴ بخش تقسیم کنید و برای هر بخش ۳۰ ثانیه وقت بگذارید.\n\n۳. **فاصله ۳۰ دقیقه‌ای بعد از غذاهای اسیدی:**\nاگر مرکبات، سرکه، گوجه‌فرنگی یا نوشابه مصرف کرده‌اید، بلافاصله مسواک نزنید! اسید خوراکی‌ها مینای دندان را به طور موقت نرم و دمینرالیزه می‌کند. اگر در این حالت مسواک بزنید، مینای نرم‌شده را می‌سایید. حداقل ۳۰ دقیقه صبر کنید تا بزاق اسید را خنثی کرده و املاح را بازگرداند، سپس مسواک بزنید.',
