        body: 'خلال دندان‌های چوبی یک ابزار متداول بعد از صرف غذا در رستوران‌ها و منازل هستند، اما در متون علمی دندانپزشکی به عنوان یکی از تروماتیک‌ترین عوامل آسیب به لثه شناخته می‌شوند. فضای بین دندانی توسط یک برآمدگی هرمی‌شکل و بسیار ظریف از بافت لثه به نام **پاپیلا (Interdental Papilla)** پر شده است که مانع از گیر غذایی و ورود باکتری‌ها به استخوان می‌شود.\n\nخطرات فاجعه‌بار خلال چوبی:\n- **له‌شدگی و تحلیل مکانیکی پاپیلا:** خلال چوبی ضخامتی بسیار بیشتر از فاصله طبیعی دندان‌ها دارد. فرو کردن آن با فشار، بافت نرم لثه را له کرده و به مرور زمان آن را از بین می‌برد؛ پدیده‌ای که باعث ایجاد فضاهای خالی زشت و مثلث‌های سیاه (Black Triangles) و [تحلیل ماندگار لثه](/articles/gum-recession-and-cervical-sensitivity-causes-treatment#causes-of-gum-recession-and-root-exposure) می‌شود.\n- **شکستن تراشه‌های چوب در شیار لثه:** الیاف خردشده چوب به راحتی در زیر لثه می‌شکنند و جا می‌مانند که واکنش شدید جسم خارجی، آبسه چرکی حاد و دردهای ضربان‌دار را به دنبال دارد.\n- **ایمن‌ترین جایگزین:** [نخ دندان‌های مومی استاندارد و مسواک‌های بین‌دندانی](/articles/oral-hygiene-tools-brush-floss-guide#flossing-sequence-and-interdental-tools) یا خلال‌های سیلیکونی نرم پزشکی (Soft-Picks) که به هیچ وجه به لثه فشار مکانیکی وارد نمی‌کنند.',
