        body: 'برای این که بیشترین فایده را از دهان‌شویه ببرید، فقط کافی است سه نکته ساده زیر را به خاطر بسپارید:\n\n۱. **بزرگ‌ترین اشتباه: آب‌کشی بعد از دهان‌شویه ممنوع!**\nخیلی از افراد بعد از چرخاندن دهان‌شویه، فوراً شیر آب را باز می‌کنند و دهانشان را پر از آب کرده و می‌شویند! با این کار، تمام فلورایدی که قرار بود روی دندان بنشیند را با دست خودتان دور می‌ریزید. دهان‌شویه را ۳۰ ثانیه قرقره کنید، بیرون تف کنید و **تا نیم ساعت نه آب بخورید، نه دهان را آب بکشید و نه چیزی میل کنید**.\n\n۲. **بهترین زمان مصرف:**\nبهترین تایم، شب‌ها دقیقاً بعد از مسواک و نخ دندان و درست قبل از خوابیدن است. وقتی می‌خوابید، بزاق کمتری ترشح می‌شود و فلوراید ساعت‌ها روی دندان‌ها استراحت می‌کند و به عمق بافت نفوذ می‌نماید.\n\n۳. **فاصله انداختن با خمیردندان:**\nکف خمیردندان اثر دهان‌شویه‌های قوی مثل کلرهگزیدین را خنثی می‌کند؛ بهتر است بین مسواک زدن و مصرف دهان‌شویه دارویی نیم ساعت فاصله بیندازید.',
