        body: 'میزان تخریب اسیدی صرفاً به عدد pH وابسته نیست، بلکه به نوع اسید و شاخصی تحت عنوان **«اسیدیته قابل تیتر» (Titratable Acidity)** بستگی دارد که نشان‌دهنده مدت‌زمانی است که بزاق برای خنثی کردن آن اسید نیاز دارد:\n\n- **اسید فسفریک (Phosphoric Acid):** ماده‌ای پرکاربرد در کولاها که پیوندهای کلسیم و فسفات در شبکه مینای دندان را هدف قرار داده و باعث دمینرالیزاسیون اولیه می‌شود.\n\n- **اسید سیتریک (Citric Acid):** معمولاً در نوشیدنی‌های ورزشی و نوشابه‌های با طعم مرکبات یافت می‌شود. اسید سیتریک علاوه بر افت pH، اثر کلاته‌کنندگی (اتصال به کلسیم) دارد و یون‌های کلسیم را از بافت مینا جدا می‌کند. همچنین اسیدیته قابل تیتر بالای آن سبب می‌شود توان دفاعی بزاق دیرتر اسید را مهار کند.\n\nدر اثر حل شدن مینا، لایه زیرین آن که عاج نام دارد نمایان شده و مجاری ظریف آن تحریکات حرارتی را به عصب منتقل می‌کنند که بیمار آن را به صورت تیر کشیدن با آب سرد تجربه می‌کند.',
