        body: 'در برابر فرسایش اسیدی، فرآورده‌های شیری به عنوان عوامل بیواکتیو محافظ دندان شناخته می‌شوند. مصرف لبنیات از سه طریق از دندان‌ها محافظت می‌کند:\n\n۱. **اشباع محیط بزاق از کلسیم و فسفات:** شیر و پنیر غلظت یون‌های معدنی آزاد بزاق را افزایش می‌دهند و از خروج املاح از بافت دندان ممانعت می‌کنند؛ نقشی بنیادین که در کنار تاثیر کلی [کلسیم و ویتامین D بر سلامت دندان و لثه](/articles/vitamins-minerals-calcium-vitamin-d-dental-health#childhood-enamel-vs-adult-teeth) به اثبات رسیده است.\n\n۲. **نقش پروتئین‌های کازئین (CPP-ACP):** شیر حاوی کمپلکس‌های پروتئینی فسفوپپتید کازئین است که کلسیم و فسفات را در سطح مینا پایدار کرده و فرآیند رمینرالیزاسیون سطحی را تقویت می‌نمایند.\n\n۳. **ظرفیت بافری پنیر:** مطالعات نشان می‌دهند مصرف یک قطعه پنیر پس از وعده غذایی، جریان ترشح بزاق را تحریک کرده و طی کمتر از ۳ دقیقه، pH اسیدی پلاک را به محدوده طبیعی و خنثی بازمی‌گرداند.',
