        body: 'سلامت بافت‌های دهان حاصل همکاری متقابل چندین ریزمغذی کلیدی است:\n\n- **منیزیم (Magnesium):** کوفاکتور ضروری برای تبدیل ویتامین D به فرم فعال بیولوژیک در کبد و کلیه است. علاوه بر این، منیزیم استحکام ساختاری بلورهای استخوانی فک را ارتقا داده و مقاومت فک در برابر نیروهای جونده را افزایش می‌دهد.\n\n- **ویتامین C (اسید اسکوربیک):** بافت لثه و الیاف پریودنتال (که دندان را به استخوان متصل نگه می‌دارند) ساختاری بر پایه پروتئین کلاژن دارند. ویتامین C عامل حیاتی در سنتز کلاژن است؛ کمبود آن موجب شکنندگی مویرگ‌های لثه و خونریزی با کمترین تحریک مسواک می‌شود.\n\n- **ویتامین K2:** فعال‌کننده پروتئین استئوکلسین است که وظیفه هدایت و رسوب یون‌های کلسیم در ماتریس استخوانی فک را بر عهده دارد و مانع از انحراف کلسیم به دیواره عروق خونی می‌شود.',
