        body: 'جدول زیر نقش هر یک از ریزمغذی‌ها را در ساختار بافت‌های دهان و دندان خلاصه می‌کند:\n\n| ریزمغذی | بافت هدف اصلی در دهان | نقش بیولوژیک و بالینی | منابع غذایی برتر |\n|---|---|---|---|\n| **کلسیم (Calcium)** | مینای دندان (کودکی) و استخوان آلوئول (بزرگسالی) | تامین تراکم معدنی و جلوگیری از تحلیل فک | شیر، پنیر، ماست، کنجد و بادام |\n| **ویتامین D3** | استخوان فک و سلول‌های ایمنی لثه | تنظیم جذب کلسیم و مهار التهاب پریودنتال | نور خورشید، ماهی‌های چرب، زرده تخم‌مرغ و مکمل |\n| **منیزیم (Magnesium)** | شبکه کریستالی استخوان فک | فعال‌سازی ویتامین D و ارتقای استحکام استخوان | مغزها، حبوبات، دانه‌ها و سبزیجات برگ‌سبز |\n| **ویتامین C** | الیاف کلاژن بافت لثه | سنتز ماتریکس کلاژنی و پیشگیری از خونریزی لثه | مرکبات، کیوی، فلفل دلمه‌ای و توت‌فرنگی |\n| **ویتامین K2** | پروتئین استئوکلسین استخوان | هدایت هدفمند کلسیم به بافت استخوانی فک | لبنیات سنتی، پنیرهای تخمیرشده و زرده تخم‌مرغ |\n\n### چهار توصیه کاربردی برای سلامت طولانی‌مدت ساختار دندان‌ها\n\n۱. **پایش دوره‌ای ویتامین D خون:** سطح خونی ۲۵(OH)D را سالانه بررسی کنید و در صورت وجود کمبود، زیر نظر پزشک اقدام به درمان نمایید.\n\n۲. **اولویت دریافت کلسیم از منابع طبیعی:** کلسیم دریافتی از مواد غذایی به همراه فسفر و پروتئین، راندمان جذب بیولوژیک بالاتری نسبت به قرص‌های مکمل دارد.\n\n۳. **استفاده روزانه از ترکیبات موضعی فلوراید:** هیچ رژیم غذایی جایگزین محافظت موضعی فلوراید نمی‌شود؛ فلوراید خمیردندان‌ها با ایجاد لایه فلوروآپاتیت، مینای دندان را در برابر اسید باکتری‌ها مقاوم می‌سازد.\n\n۴. **اهمیت تغذیه در دوران بارداری و تکامل اولیه کودک:** تشکیل بلورهای مینای دندان‌های کودک در این دوران صورت می‌گیرد و تغذیه اصولی مادر مستقیماً کیفیت مینای دندان فرزند را پایه‌ریزی می‌کند.',
