        body: 'پیدایش لکه‌های سفید مات و گچی روی سطح دندان، به‌ویژه در مرز لثه یا اطراف براکت‌های ارتودنسی، اولین نشانه بالینی از شروع پوسیدگی دندان است. این ضایعات که در متون علمی دندانپزشکی به عنوان **«White Spot Lesion»** شناخته می‌شوند، هنوز تبدیل به سوراخ یا حفره نشده‌اند.\n\nمکانیسم پیدایش لکه سفید پوسیدگی:\n- **تجمع طولانی‌مدت پلاک میکروبی:** عدم مسواک زدن دقیق باعث ماندگاری بیوفیلم باکتری‌ها در طوق دندان می‌شود.\n- **دمینرالیزاسیون زیرسطحی:** اسید تولیدشده توسط باکتری‌ها از منافذ میکروسکوپی مینا عبور کرده و املاح کلسیم و فسفات را از لایه زیرین خارج می‌کند.\n- **تغییر بازتاب نور:** با خالی شدن بلورهای معدنی و پر شدن منافذ با آب و هوا، ضریب شکست نور تغییر کرده و دندان در آن نقطه به جای شفافیت طبیعی، ظاهری گچی و مات به خود می‌گیرد؛ پدیده‌ای که نحوه تخریب اسیدی آن در تحلیل [قندها، کربوهیدرات‌ها و منحنی استفان](/articles/sugars-carbohydrates-and-dental-health#how-sugars-cause-cavities-stephan-curve) تشریح شده است.',
