        body: 'جدول زیر تفاوت‌های بالینی سه علت اصلی ایجاد لکه‌های سفید روی دندان را خلاصه می‌کند:\n\n| ویژگی بالینی | پوسیدگی اولیه (White Spot) | فلوروزیس دندانی | هیپوپلازی و نقص تکاملی |\n|---|---|---|---|\n| **علت بیولوژیک** | اسید پلاک میکروبی و تخمیر قند | دریافت بیش از حد فلوراید در کودکی | تب بالا، تروما یا اختلال تغذیه‌ای |\n| **محل استقرار** | طوق دندان و دور براکت ارتودنسی | نوک و لبه دندان‌ها به صورت متقارن | پراکنده و متغیر روی تاج دندان |\n| **وضعیت سطح مینا** | مات، متخلخل و مستعد سوراخ شدن | سخت، براق و مقاوم به پوسیدگی | فرورفته، نازک یا دارای شیار |\n| **پاسخ به رمینرالیزاسیون** | بسیار عالی با فلوراید و کلسیم | بدون تغییر ساختاری (نیازمند زیبایی) | بدون پاسخ به فلوراید خوراکی |\n| **بهترین درمان کلینیکی** | فلوراید وارنیش دوره‌ای و بهداشت | رزین اینفیلتریشن (Icon) یا بلیچینگ | باندینگ کامپوزیت یا لمینت |\n\n### چهار اصل مراقبتی برای پیشگیری و محو لکه‌های سفید دندان\n\n۱. **بهداشت وسواس‌گونه حین درمان ارتودنسی:** استفاده از مسواک‌های بین‌دندانی مانع از تجمع پلاک اسیدی در اطراف براکت‌ها و ایجاد لکه گچی می‌شود.\n\n۲. **کاربرد روزانه خمیردندان‌های حاوی فلوراید:** حفظ تماس منظم مینای دندان با فلوراید استاندارد اجازه دمینرالیزاسیون اولیه را نمی‌دهد.\n\n۳. **پایش منابع آب مصرفی کودکان:** برای پیشگیری از فلوروزیس، از مصرف افراطی مکمل‌های فلوراید در مناطقی که آب لوله‌کشی فلوراید طبیعی دارد خودداری نمایید.\n\n۴. **مراجعه در مراحل اولیه تغییر رنگ:** به محض مشاهده کدر شدن لبه دندان‌ها به کلینیک مراجعه کنید تا پیش از حفر شدن دندان، با پروتکل‌های غیرتهاجمی درمان شود.',
