        body: 'اگر یک دندان شیری به دلیل پوسیدگی غیرقابل‌نگهداری یا سهل‌انگاری پیش از موعد کشیده شود، دندان‌های مجاور به سمت فضای خالی کج و منحرف می‌شوند و دندان‌های فک مقابل نیز به سمت فضای خالی رشد می‌کنند. نتیجه این پدیده، بسته شدن فضای لازم برای رویش دندان دائمی زیرین و نهفته ماندن آن یا رویش به صورت کج در سقف دهان یا پشت دندان‌های دیگر است. به‌ویژه با رویش [دندان آسیاب اول دائمی یا دندان ۶ سالگی](/articles/tooth-eruption-timeline-and-stages#first-permanent-molar-six-year-tooth)، فشار رو به جلو می‌تواند تمام فضای خالی باقیمانده را مسدود کند. در شرایطی که کشیدن دندان شیری اجتناب‌ناپذیر باشد، دندانپزشک بلافاصله از دستگاهی به نام «فضانگهدار» (Space Maintainer) اعم از ثابت یا متحرک در چارچوب [ارتودنسی پیشگیرانه کودکان](/articles/pediatric-oral-habits-and-preventive-orthodontics#what-is-preventive-orthodontics-age-7) استفاده می‌کند تا فضای رویش دندان دائمی تا رسیدن سن مناسب کاملاً محفوظ بماند.',
