        body: 'باور بسیار رایجی وجود دارد که نوشابه‌های رژیمی یا زیرو (Zero / Diet) چون فاقد قند هستند آسیبی به دندان نمی‌زنند؛ اما حقیقت بالینی دندانپزشکی چیز دیگری است:\n\n- **اسیدیته بالا مستقل از قند است:** نوشابه‌های زیرو نیز حاوی اسید فسفریک و سیتریک هستند و pH آن‌ها در حدود ۲.۸ تا ۳.۲ است.\n- **فرسایش شیمیایی بدون باکتری رخ می‌دهد:** اسید به تنهایی ساختار هیدروکسی‌آپاتیت را حل می‌کند، حتی اگر هیچ قندی برای باکتری‌ها وجود نداشته باشد.\n- **ترکیبات طعم‌دهنده خورنده هستند:** مواد نگه‌دارنده و اسیدهای طعم‌دهنده شدت چسبندگی اسید به مینای دندان را افزایش می‌دهند.\n- **تغییر اکوسیستم میکروبی دهان:** شیرین‌کننده‌های مصنوعی مانند آسپارتام نیز می‌توانند تعادل باکتری‌های مفید فلور دهان را دستخوش تغییر کنند.',
