        body: 'اگر به مصرف نوشیدنی‌های گازدار تمایل دارید یا در مهمانی‌ها آن را می‌نوشید، رعایت این توصیه‌ها آسیب را به حداقل می‌رساند:\n\n۱. **استفاده از نی هنگام نوشیدن:** نوشیدن با نی تماس مستقیم مایع اسیدی با سطوح دندان‌های قدامی را تا حد زیادی کاهش می‌دهد.\n۲. **شستشوی فوری دهان با آب ساده:** بلافاصله پس از اتمام نوشابه، یک لیوان آب معمولی بنوشید یا دهان را بچرخانید تا اسید محیط دهان رقیق شود.\n۳. **پرهیز جدی از مسواک زدن فوری (تا ۴۵ دقیقه):** اسید مینای دندان را موقتاً نرم و دمینرالیزه می‌کند؛ مسواک زدن بلافاصله پس از نوشابه باعث سایش فیزیکی شدید و تراشیده شدن مینای نرم می‌شود.\n۴. **استفاده از خمیردندان‌های حاوی فلوراید و ضدحساسیت:** فلوراید به رمینرالیزاسیون و بازسازی مجدد کلسیم در بلورهای مینا کمک بسزایی می‌کند.',
