        body: 'برای پشت سر گذاشتن ایمن این دوران و حفظ درخشش و استحکام دندان‌ها، دندانپزشکان پروتکل مرحله‌به‌مرحله زیر را به مادران توصیه می‌کنند:\n\n۱. **روش صحیح مواجهه با تهوع و استفراغ:** پس از هر بار تهوع، دهان خود را با یک لیوان آب گرم مخلوط با نصف قاشق چای‌خوری جوش‌شیرین (بی‌کربنات سدیم) شستشو دهید تا اسید فوراً خنثی شود. حداقل ۴۵ دقیقه برای مسواک زدن صبر کنید.\n۲. **کنترل تهوع هنگام مسواک زدن:** اگر طعم خمیردندان یا اندازه سر مسواک باعث تحریک تهوع و رفلاکس می‌شود، از مسواک‌های با سر کوچک (مسواک مخصوص کودک) و خمیردندان‌های بدون کف یا طعم ملایم استفاده نمایید.\n۳. **استفاده مستمر از نخ دندان و مسواک بین‌دندانی:** هیچ شوینده‌ای جایگزین نخ دندان برای زدودن پلاک در ناحیه طوق لثه نمی‌شود؛ روزی یک بار قبل از خواب حتماً نخ دندان بکشید.\n۴. **جرم‌گیری تخصصی در کلینیک:** جرم‌گیری و پاکسازی حرفه‌ای پلاک در [سه‌ماهه دوم که زمان طلایی درمان‌هاست](/articles/dental-treatment-safety-and-xray-in-pregnancy#dental-treatment-timing-trimester-breakdown) نه‌تنها بی‌خطر است، بلکه التهاب ژنژیویت بارداری را به حداقل می‌رساند و مانع از گسترش بیماری به ریشه دندان می‌شود.\n۵. **مصرف کافی کلسیم و ویتامین D از راه تغذیه:** مصرف لبنیات کم‌چرب، مغزها و مکمل‌های دارویی تجویز شده توسط متخصص زنان، ذخایر استخوانی مادر را در طول شیردهی حفظ کرده و سلامت ساختار استخوان فک را تضمین می‌کند.',
