        id: 'general-principles-of-prescription-in-pregnancy',
        title: 'اصول کلی تجویز دارو؛ هماهنگی دندانپزشک با متخصص زنان و خودداری از خوددرمانی',
        body: 'برای دستیابی به بیشترین ایمنی مادر و نوزاد، دندانپزشکان همواره از سه اصل بنیادین در نسخه نویسی پیروی می‌کنند:\n\n۱. **پرهیز مطلق از خوددرمانی:** مصرف هرگونه قرص مسکن یا چرک‌خشک‌کن مانده در منزل بدون دستور دندانپزشک و پزشک زنان می‌تواند سلامت جنین را در معرض خطر قرار دهد.\n۲. **اصل حداقل دوز موثر در کوتاه‌ترین زمان:** داروها در کمترین دوز درمانی که درد یا عفونت را برطرف سازد و در کوتاه‌ترین دوره زمانی تجویز می‌شوند.\n۳. **هماهنگی بین‌رشته‌ای در بارداری‌های پرخطر:** در مادرانی که با بیماری‌های زمینه‌ای نظیر دیابت بارداری، پره‌اکلامپسی، فشار خون بالا یا سابقه سقط مکرر مواجه هستند، دندانپزشک پیش از تجویز داروهای خاص با پزشک متخصص زنان مشاوره بالینی انجام می‌دهد.',
