        body: 'بسیاری از بیماران می‌پرسند: «وقتی عصب دندان خارج شده است، چرا دندان هنگام فشار دادن یا غذا خوردن تیر می‌کشد؟» برای درک این موضوع باید توجه داشت که عصب داخل دندان برداشته شده، اما **الیاف نگه‌دارنده دور ریشه دندان و استخوان فک (رباط پریودنتال / PDL)** کاملاً زنده و سرشار از پایانه‌های عصبی حسی هستند.\n\n### علل اصلی درد در روزهای نخست پس از درمان:\n\n۱. **التهاب فیزیکی اطراف ریشه (Periapical Inflammation):** همان‌طور که در [مراحل گام‌به‌گام درمان ریشه](/articles/root-canal-treatment-steps-success-rate-prognosis#step-by-step-root-canal-procedure) شرح داده شد، چرخش فایل‌های روتاری و شستشوی ریشه برای پاکسازی میکروب‌ها، واکنشی التهابی موقت در بافت استخوانی انتهای ریشه ایجاد می‌کند که معمولاً طی ۳ تا ۷ روز فروکش می‌کند.\n۲. **بلندی پانسمان موقت یا ترمیم تاج:** حتی کسری از میلی‌متر بلندی پانسمان باعث می‌شود هنگام بستن فک‌ها، تمام نیروی عضلات جونده روی همین یک دندان وارد شود و درد کوبنده‌ای در استخوان ایجاد کند. این وضعیت به سادگی با یک تنظیم ارتفاع یک دقیقه‌ای در مطب برطرف می‌شود.\n۳. **درد حین کار دندانپزشکی چطور مهار می‌شود؟** در دندان‌های با التهاب حاد (اصطلاحاً دندان‌های داغ / Hot Teeth)، اسیدی بودن بافت ممکن است اثر بی‌حسی را کاهش دهد. دندانپزشک مجرب با استفاده از **تکنیک‌های بی‌حسی مکمل (تزریق اینترالیگامنتاری، اینتراسپتال یا داخل پالپ)** بی‌حسی صددرصدی و عمیق را تضمین می‌کند تا بیمار هیچ رنجی نکشد.',
