        body: 'در درصد اندکی از بیماران (حدود ۲ تا ۵ درصد موارد)، بیمار ساعاتی پس از جلسه عصب‌کشی یا روز بعد با درد طاقت‌فرسا و تورم ناگهانی لثه یا صورت مواجه می‌شود. در متون تخصصی اندودانتیکس به این پدیده **فلرآپ (Flare-up)** گفته می‌شود.\n\n### ریشه‌های بیولوژیک ایجاد فلرآپ:\n\n- **تغییر اکوسیستم باکتری‌های بی‌هوازی:** ورود اکسیژن یا تغییر تعادل میکروبی داخل کانال در دندان‌های عفونی با نکروز قدیمی، باکتری‌های خفته را به شکل موقت تهاجمی می‌سازد.\n- **خروج اندوتوکسین‌های باکتریایی از نوک ریشه:** خروج میکروسکوپی بقایای بیوفیلم به بیرون از سوراخ آپیکال، واکنش دفاعی شدید سیستم ایمنی و آزادسازی حجم عظیمی از هیستامین و پروستاگلاندین‌ها را تحریک می‌کند.\n\n### پروتکل اورژانس درمان فلرآپ در کلینیک:\n\n۱. **تنظیم و خارج کردن دندان از تماس جویدن (Occlusal Reduction):** اولین گام، تراش بسیار جزئی سطح تماس دندان است تا در زمان بلع یا بستن دهان هیچ فشاری به آن نیاید.\n۲. **شستشوی مجدد و قرار دادن داروی هیدروکسید کلسیم:** پانسمان باز شده، کانال با سرم ضدعفونی شسته شده و خمیر دارویی کلسیم هیدروکسید برای مهار اسیدیته و سرکوب باکتری‌ها در کانال گذاشته می‌شود.\n۳. **برش و درناژ در صورت تورم مواج (Incision & Drainage):** در صورت وجود ورم متمرکز در بافت لثه، یک برش ظریف برای خروج چرک و کاهش فوری فشار بافتی داده می‌شود.',
