        body: 'یکی از باورهای اشتباه و خسارت‌بار در میان بیماران این است که تصور می‌کنند دندانی که دچار ورم، چرک و آبسه حاد شده «فاسد و غیرقابل استفاده» است و باید فوراً کشیده شود! واقعیت علمی این است که **آبسه، پاسخ دفاعی استخوان به سموم باکتریایی داخل کانال است؛ نه بیماری خود ریشه**.\n\n| باور نادرست عمومی | واقعیت بیولوژیک و درمان استاندارد |\n| :--- | :--- |\n| دندانی که آبسه کرده ریشه‌اش فاسد شده و باید کشیده شود | با پاکسازی داخل کانال ریشه، عامل عفونت حذف شده و استخوان فک آبسه را کاملاً بازسازی می‌کند |\n| تا زمانی که دندان ورم دارد نباید کار دندانپزشکی انجام داد | باز کردن راه خروج چرک از داخل کانال یا لثه، فوری‌ترین و موثرترین درمان کاهش ورم است |\n| مصرف خودسرانه آموکسی‌سیلین به تنهایی عفونت ریشه را درمان می‌کند | آنتی‌بیوتیک از راه خون به داخل مجرای دندان بدون عصب نمی‌رسد؛ تنها راه درمان پاکسازی مکانیکی کانال است |\n\n### آنتی‌بیوتیک چه زمانی واقعاً لازم است؟\nبر اساس راهنماهای رسمی انجمن متخصصان درمان ریشه آمریکا (AAE)، تجویز آنتی‌بیوتیک سیستمیک تنها در صورتی مجاز است که عفونت علائم عمومی ایجاد کند (مانند **تب، لرز، بی‌حالی، ورم منتشر صورت یا بزرگی غدد لنفاوی زیر فک**). در آبسه‌های موضعی بدون تب، درمان بالینی و درناژ کانال برای بهبودی کامل کافی است و تجویز بی‌رویه آنتی‌بیوتیک فقط مقاومت میکروبی به بار می‌آورد.',
