        body: 'یکی از مهم‌ترین یافته‌های علم دندانپزشکی مدرن که در پژوهش کلاسیک و مشهور دکتر ری و تروپ (Ray & Trope) به اثبات رسید این است که **کیفیت ترمیم تاجی دندان به اندازه کیفیت خود عصب‌کشی و حتی فراتر از آن در بقای درازمدت دندان نقش دارد**.\n\n### خطرات تعویق پر کردن دائمی تاج:\n\n- **نفوذپذیری پانسمان موقت:** پانسمان‌های خمیری موقت که در پایان جلسه عصب‌کشی روی دندان قرار می‌گیرند، عمر مفیدی بین ۲ تا حداکثر ۴ هفته دارند. پس از این مدت، در اثر سایش با غذا و رطوبت دهان، دچار ریزنشت (Microleakage) شده و باکتری‌های بزاق به راحتی از کناره‌های پانسمان عبور کرده و خود را به انتهای ریشه می‌رسانند.\n- **عفونت مجدد گوتاپرکا:** اگر دندان عصب‌کشی‌شده بیش از یک ماه بدون پرکردگی دائمی و تنها با پانسمان رها شود، حتی اگر عصب‌کشی بی‌نقص انجام شده باشد، کانال‌ها مجدداً آلوده شده و نیازمند شستشو و درمان مجدد خواهند شد.\n- **زمان‌بندی طلایی پر کردن دائمی:** توصیه اکید دندانپزشکی این است که ترمیم نهایی تاج ظرف **۱ تا ۲ هفته پس از اتمام عصب‌کشی** (پس از اطمینان از رفع دردهای اولیه) انجام شود.',
